# FlowGuard frontend — Nginx reverse-proxy config (envsubst template).
#
# This file is copied to /etc/nginx/templates/default.conf.template; the
# official nginx image substitutes ${...} environment variables at container
# start, so NO backend URL is ever baked into the image or the JS bundle.
#
# Runtime environment variables (set on the Cloud Run *frontend* service):
#   PORT         — injected automatically by Cloud Run (do not set manually)
#   BACKEND_HOST — hostname ONLY of the Node backend Cloud Run service
#                  e.g. flowguard-server-xxxxxxxxxx.asia-southeast1.run.app
#
# Same-origin architecture: the browser only ever talks to THIS origin.
#   /api/*  and /user/*  -> Node backend   (mirrors the Vite dev proxy)
#   everything else      -> the React SPA, falling back to index.html
#                           so React Router deep links work on refresh.
#
# The Python AI service is PRIVATE (no unauthenticated Cloud Run access) and
# is deliberately NOT proxied here: all AI traffic — facial recognition,
# tracking, AND the YOLO object-detection endpoints (/api/yolo/*) — goes
# through the Node backend, which authenticates the user (JWT/RBAC) and then
# calls the AI service with a Google-signed ID token + X-AI-Service-Key.

server {
    listen ${PORT};
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    # Base64 webcam frames are large; match the backend's 50 MB JSON limit.
    client_max_body_size 50m;

    gzip on;
    gzip_types text/css application/javascript application/json image/svg+xml;

    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # ---- Node backend (same paths the Vite dev proxy forwards) ----
    location /api/ {
        proxy_pass https://${BACKEND_HOST};
        proxy_http_version 1.1;
        proxy_ssl_server_name on;
        proxy_set_header Host ${BACKEND_HOST};
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        # /api/yolo/analyze-frame proxies model inference — allow slow frames.
        proxy_read_timeout 120s;
    }

    location /user/ {
        proxy_pass https://${BACKEND_HOST};
        proxy_http_version 1.1;
        proxy_ssl_server_name on;
        proxy_set_header Host ${BACKEND_HOST};
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_read_timeout 120s;
    }

    # ---- Static assets: long cache for hashed files ----
    location /assets/ {
        expires 30d;
        add_header Cache-Control "public, immutable";
        try_files $uri =404;
    }

    # ---- React Router SPA fallback ----
    location / {
        try_files $uri $uri/ /index.html;
    }
}

